若您刷新后仍然出现此问题. 请加网站客服反馈' ]); } if (System::_getInt('vcode_shop_buy') === 1) { try { $this->validateCaptcha($request); } catch (\Throwable $e) { return self::renderResultPage($request, ['msg' => trans('validation.captcha')]); } } $category_id = (int)$request->input('category_id'); $product_id = (int)$request->input('product_id'); $count = (int)$request->input('count'); $coupon = $request->input('coupon'); $contact = $request->input('contact'); $contact_ext = $request->input('contact_ext') ?? null; $send_sms = !empty(@json_decode($contact_ext, true)['_mobile']); $pay_id = (int)$request->input('pay_id'); if (!$category_id || !$product_id) return self::renderResultPage($request, ['msg' => trans('shop.product.required')]); if (strlen($contact) < 1) return self::renderResultPage($request, ['msg' => trans('shop.contact.required')]); $query_password = null; if(System::_getInt('order_query_password_open')){ $query_password = $request->input('query_password'); if (strlen($query_password) < 1){ return self::renderResultPage($request, ['msg' => trans('shop.query_password.required')]); } if(strlen($query_password) < 6 || Helper::isWakePassword($query_password)){ return self::renderResultPage($request, ['msg' => trans('shop.query_password.weak')]); } } $category = Category::findOrFail($category_id); $product = Product::where('id', $product_id) ->where('category_id', $category_id) ->where('enabled', 1) ->with(['user'])->first(); if ($product == null || $product->user == null) return self::renderResultPage($request, ['msg' => trans('shop.product.not_found')]); if (!$product->enabled) { return self::renderResultPage($request, ['msg' => trans('shop.product.not_on_sell')]); } if ($product->password_open) { if ($product->password !== $request->input('product_password')) { return self::renderResultPage($request, ['msg' => trans('shop.product.password_error')]); } } else { if ($category->password_open) { if ($category->password !== $request->input('category_password')) { if ($category->getTmpPassword() !== $request->input('category_password')) { return self::renderResultPage($request, ['msg' => trans('shop.category.password_error')]); } } } } if ($count < $product->buy_min) return self::renderResultPage($request, ['msg' => trans('shop.product.buy_min', ['num' => $product->buy_min])]); if ($count > $product->buy_max) return self::renderResultPage($request, ['msg' => trans('shop.product.buy_max', ['num' => $product->buy_max])]); if ($product->count < $count) return self::renderResultPage($request, ['msg' => trans('shop.product.out_of_stock')]); $pay = \App\Pay::find($pay_id); if ($pay == null || !$pay->enabled) { return self::renderResultPage($request, ['msg' => trans('shop.pay.not_found')]); } $per_price = $product->price; if ($product->price_whole) { $price_whole = json_decode($product->price_whole, true); for ($i = count($price_whole) - 1; $i >= 0; $i--) { if ($count >= (int)$price_whole[$i][0]) { $per_price = (int)$price_whole[$i][1]; break; } } } $price = $count * $per_price; $pay_money = $price; $discount_fee = 0; $used_coupon = null; if ($product->support_coupon && strlen($coupon) > 0) { $coupons = \App\Coupon::where('user_id', $product->user_id) ->where('coupon', $coupon) ->where('expire_at', '>', Carbon::now()) ->whereRaw('`count_used`<`count_all`')->get(); foreach ($coupons as $c) { if ($c->category_id === -1 || ($c->category_id === $category_id && ($c->product_id === -1 || $c->product_id === $product_id))) { if ($c->discount_type === \App\Coupon::DISCOUNT_TYPE_AMOUNT && $pay_money >= $c->discount_val) { $used_coupon = $c; $discount_fee = $c->discount_val; break; } if ($c->discount_type === \App\Coupon::DISCOUNT_TYPE_PERCENT) { $used_coupon = $c; $discount_fee = (int)round($pay_money * $c->discount_val / 100); break; } } } if ($used_coupon === null) { return self::renderResultPage($request, ['msg' => trans('shop.coupon.invalid')]); } $pay_money -= $discount_fee; } $system_fee = (int)round($pay_money * $pay->fee_system); $merchant_income = $pay_money - $system_fee; $sms_price = $send_sms ? System::_getInt('sms_price', 10) : 0; $pay_money += $sms_price; $cost = $count * $product->cost; $order_no = \App\Order::unique_no(); try { DB::transaction(function () use ( $product, $order_no, $used_coupon, $contact, $contact_ext, $query_password, $customer, $count, $cost, $price, $sms_price, $discount_fee, $pay_money, $pay, $system_fee, $merchant_income ) { if ($used_coupon) { $used_coupon->status = \App\Coupon::STATUS_USED; $used_coupon->count_used++; $used_coupon->save(); $remark = '使用优惠券: ' . $used_coupon->coupon; } else { $remark = null; } $order = new \App\Order([ 'user_id' => $product->user_id, 'order_no' => $order_no, 'product_id' => $product->id, 'product_name' => $product->name, 'count' => $count, 'ip' => Helper::getIP(), 'customer' => $customer, 'contact' => $contact, 'contact_ext' => $contact_ext, 'query_password' => $query_password, 'cost' => $cost, 'price' => $price, 'sms_price' => $sms_price, 'discount' => $discount_fee, 'paid' => $pay_money, 'pay_id' => $pay->id, 'fee' => $system_fee, 'system_fee' => $system_fee, 'income' => $merchant_income, 'status' => \App\Order::STATUS_UNPAY, 'remark' => $remark, 'created_at' => Carbon::now(), ]); $order->saveOrFail(); }); } catch (\Throwable $e) { Log::error('Shop.Pay.buy 下单失败', ['exception' => $e]); return self::renderResultPage($request, ['msg' => trans('shop.pay.internal_error')]); } if ($pay_money === 0) { $this->shipOrder($request, $order_no, $pay_money, null); return redirect()->away(route('pay.result', [$order_no], false)); } $order_name = $order_no; return $this->goPay($request, $order_no, $order_name, $pay, $pay_money); } function pay(Request $request, $order_no) { $order = \App\Order::whereOrderNo($order_no)->first(); if ($order == null) { return self::renderResultPage($request, ['msg' => trans('shop.order.not_found')]); } if ($order->status !== \App\Order::STATUS_UNPAY) { return redirect('/pay/result/' . $order_no); } $logTag = 'pay: ' . $order->pay_id; $pay = $order->pay; if (!$pay) { \Log::error($logTag . ' cannot find Pay'); return $this->renderResultPage($request, ['msg' => trans('shop.pay.not_found')]); } $logTag .= ',' . $pay->driver; $config = json_decode($pay->config, true); $config['payway'] = $pay->way; $config['out_trade_no'] = $order_no; try { $this->payApi = GatewayPay::getDriver($pay); } catch (\Exception $e) { \Log::error($logTag . ' cannot find Driver: ' . $e->getMessage()); return $this->renderResultPage($request, ['msg' => trans('shop.pay.driver_not_found')]); } if ($this->payApi->verify($config, function ($order_no, $amount, $trade_no) use ($request) { try { $this->shipOrder($request, $order_no, $amount, $trade_no); } catch (\Exception $e) { $this->renderResultPage($request, [ 'success' => false, 'msg' => $e->getMessage() ]); } })) { \Log::notice($logTag . ' already success' . "\n\n"); return redirect('/pay/result/' . $order_no); } if ($order->created_at < Carbon::now()->addMinutes(-System::_getInt('order_pay_timeout_minutes', 5))) { return $this->renderResultPage($request, ['msg' => trans('shop.order.expired')]); } $product = Product::where('id', $order->product_id) ->where('enabled', 1) ->first(); if ($product == null) { return self::renderResultPage($request, ['msg' => trans('shop.product.not_on_sell')]); } $product->setAttribute('count', count($product->cards) ? $product->cards[0]->count : 0); if ($product->count < $order->count) { return self::renderResultPage($request, ['msg' => trans('shop.product.out_of_stock')]); } $order_name = $order_no; return $this->goPay($request, $order_no, $order_name, $pay, $order->paid); } function qrcode(Request $request, $order_no, $pay_file) { $order = \App\Order::whereOrderNo($order_no)->with('product')->first(); if ($order == null) { return self::renderResultPage($request, ['msg' => trans('shop.order.not_found')]); } if ($order->created_at < Carbon::now()->addMinutes(-System::_getInt('order_pay_timeout_minutes', 5))) { return $this->renderResultPage($request, ['msg' => trans('shop.order.expired')]); } if ($order->product_id !== \App\Product::ID_API) { $product = $order->product; if ($product == null) { return self::renderResultPage($request, ['msg' => trans('shop.product.not_found')]); } if ($product->count < $order->count) { return self::renderResultPage($request, ['msg' => trans('shop.product.out_of_stock')]); } } if (strpos($pay_file, '..')) { return $this->msg(trans('shop.you_are_sb')); } return view('pay/' . $pay_file, [ 'pay_id' => $order->pay_id, 'name' => $order->product_id === \App\Product::ID_API ? $order->api_out_no : ($order->product->name . ' x ' . $order->count . '件'), 'amount' => $order->paid, 'qrcode' => $request->get('url'), 'id' => $order_no ]); } function qrQuery(Request $request, $pay_id) { $order_no_outer = $request->input('id'); if (isset($order_no_outer[5])) { return self::payReturn($request, $pay_id, $order_no_outer); } else { return Response::fail('order_no error'); } } function payReturn(Request $request, $pay_id, $order_no = null) { $logTag = 'payReturn: ' . $pay_id; \Log::debug($logTag); $pay = \App\Pay::where('id', $pay_id)->first(); if (!$pay) { return $this->renderResultPage($request, [ 'success' => 0, 'msg' => trans('shop.pay.not_found') ]); } $logTag .= ',' . $pay->driver; if ($order_no && isset($order_no[5])) { $order = \App\Order::whereOrderNo($order_no)->firstOrFail(); if ($order && ($order->status === \App\Order::STATUS_PAID || $order->status === \App\Order::STATUS_SUCCESS)) { \Log::notice($logTag . ' already success' . "\n\n"); if ($request->ajax()) { return self::renderResultPage($request, [ 'success' => 1, 'data' => '/pay/result/' . $order_no ], [ 'order' => $order ]); } else { return redirect('/pay/result/' . $order_no); } } } try { $this->payApi = GatewayPay::getDriver($pay); } catch (\Exception $e) { \Log::error($logTag . ' cannot find Driver: ' . $e->getMessage()); return $this->renderResultPage($request, [ 'success' => 0, 'msg' => trans('shop.pay.driver_not_found') ]); } $config = json_decode($pay->config, true); $config['out_trade_no'] = $order_no; $config['payway'] = $pay->way; Log::debug($logTag . ' will verify'); if ($this->payApi->verify($config, function ($order_no_, $amount, $trade_no) use ($request, $logTag, &$order_no) { $order_no = $order_no_; try { Log::debug($logTag . " shipOrder start, order_no: $order_no, amount: $amount, trade_no: $trade_no"); $this->shipOrder($request, $order_no, $amount, $trade_no); Log::debug($logTag . ' shipOrder end, order_no: ' . $order_no); } catch (\Exception $e) { Log::error($logTag . ' shipOrder Exception: ' . $e->getMessage(), ['exception' => $e]); } })) { Log::debug($logTag . ' verify finished: 1' . "\n\n"); if ($request->ajax()) { return self::renderResultPage($request, [ 'success' => 1, 'data' => '/pay/result/' . $order_no ]); } else { return redirect('/pay/result/' . $order_no); } } else { Log::debug($logTag . ' verify finished: 0' . "\n\n"); return $this->renderResultPage($request, [ 'success' => 0, 'msg' => trans('shop.pay.verify_failed') ]); } } function payNotify(Request $request, $pay_id) { $logTag = 'payNotify pay_id: ' . $pay_id; Log::debug($logTag); $pay = \App\Pay::where('id', $pay_id)->first(); if (!$pay) { Log::error($logTag . ' cannot find PayModel'); echo 'fail'; exit; } $logTag .= ',' . $pay->driver; try { $this->payApi = GatewayPay::getDriver($pay); } catch (\Exception $e) { Log::error($logTag . ' cannot find Driver: ' . $e->getMessage()); echo 'fail'; exit; } $config = json_decode($pay->config, true); $config['payway'] = $pay->way; $config['isNotify'] = true; Log::debug($logTag . ' will verify'); $ret = $this->payApi->verify($config, function ($order_no, $amount, $trade_no) use ($request, $logTag) { try { Log::debug($logTag . " shipOrder start, order_no: $order_no, amount: $amount, trade_no: $trade_no"); $this->shipOrder($request, $order_no, $amount, $trade_no); Log::debug($logTag . ' shipOrder end, order_no: ' . $order_no); } catch (\Exception $e) { Log::error($logTag . ' shipOrder Exception: ' . $e->getMessage()); } }); Log::debug($logTag . ' notify finished: ' . (int)$ret . "\n\n"); exit; } function result(Request $request, $order_no) { $order = \App\Order::where('order_no', $order_no)->first(); if ($order == null) { return self::renderResultPage($request, ['msg' => trans('shop.order.not_found')]); } if ($order->status === \App\Order::STATUS_PAID) { $qq = $order->user->qq; if ($order->product) { if ($order->product->delivery === \App\Product::DELIVERY_MANUAL) { $msg = trans('shop.order.msg_product_manual_please_wait'); } else { $msg = trans('shop.order.msg_product_out_of_stock_not_send'); } } else { $msg = trans('shop.order.msg_product_deleted'); } if ($qq) { $msg .= '<br><a href="http://wpa.qq.com/msgrd?v=3&uin=' . $qq . '&site=qq&menu=yes" target="_blank">客服QQ:' . $qq . '</a>'; } return self::renderResultPage($request, [ 'success' => false, 'title' => trans('shop.order_is_paid'), 'msg' => $msg ], [ 'order' => $order ]); } elseif ($order->status >= \App\Order::STATUS_SUCCESS) { return self::showOrderResult($request, $order); } return self::renderResultPage($request, [ 'success' => false, 'msg' => $order->remark ? trans('shop.order_process_failed_because', ['reason' => $order->remark]) : trans('shop.order_process_failed_default') ], [ 'order' => $order ]); } function renderResultPage(Request $request, $result, $append = []) { if ($request->ajax()) { if (@$result['success']) { return Response::success($result['data']); } else { return Response::fail('error', $result['msg']); } } else { return view('pay.result', array_merge([ 'result' => $result, 'data' => $append ], $append)); } } function shipOrder($request, $order_no, $amount, $trade_no) { $order = \App\Order::whereOrderNo($order_no)->first(); if ($order === null) { Log::error('shipOrder: No query results for model [App\Order:' . $order_no . ',trade_no:' . $trade_no . ',amount:' . $amount . ']. die(\'success\');'); die('success'); } if ($order->paid > $amount) { Log::alert('shipOrder, price may error, order_no:' . $order_no . ', paid:' . $order->paid . ', $amount get:' . $amount); $order->remark = '支付金额(' . sprintf('%0.2f', $amount / 100) . ') 小于 订单金额(' . sprintf('%0.2f', $order->paid / 100) . ')'; $order->save(); throw new \Exception($order->remark); } $product = null; if ($order->status === \App\Order::STATUS_UNPAY) { Log::debug('shipOrder.first_process:' . $order_no); if (FundHelper::orderSuccess($order->id, function ($locked_order) use ($trade_no, &$order, &$product) { $order = $locked_order; if ($order->status !== \App\Order::STATUS_UNPAY) { \Log::debug('Shop.Pay.shipOrder: .first_process:' . $order->order_no . ' already processed! #2'); return false; } $product = $order->product()->lockForUpdate()->firstOrFail(); $order->pay_trade_no = $trade_no; $order->paid_at = Carbon::now(); if ($product->delivery === \App\Product::DELIVERY_MANUAL) { $order->status = \App\Order::STATUS_PAID; $order->send_status = \App\Order::SEND_STATUS_CARD_UN; $order->saveOrFail(); return true; } if ($product->delivery === \App\Product::DELIVERY_API) { $cards = $product->createApiCards($order); } else { $cards = Card::where('product_id', $order->product_id) ->whereRaw('`count_sold`<`count_all`') ->take($order->count)->lockForUpdate()->get(); } $cards_enough = false; if (count($cards) === $order->count) { $cards_enough = true; } else { if (count($cards)) { foreach ($cards as $card) { if ($card->type === \App\Card::TYPE_REPEAT && $card->count >= $order->count) { $cards = [$card]; $cards_enough = true; break; } } } } if ($cards_enough === false) { Log::alert('Shop.Pay.shipOrder: 订单:' . $order->order_no . ', 购买数量:' . $order->count . ', 卡数量:' . count($cards) . ' 卡密不足(已支付 未发货)'); $order->status = \App\Order::STATUS_PAID; $order->saveOrFail(); return true; } else { $card_ids = []; foreach ($cards as $card) { $card_ids[] = $card->id; } $order->cards()->attach($card_ids); if (count($cards) === 1 && $cards[0]->type === \App\Card::TYPE_REPEAT) { \App\Card::where('id', $card_ids[0])->update([ 'status' => \App\Card::STATUS_SOLD, 'count_sold' => DB::raw('`count_sold`+' . $order->count) ]); } else { \App\Card::whereIn('id', $card_ids)->update([ 'status' => \App\Card::STATUS_SOLD, 'count_sold' => DB::raw('`count_sold`+1') ]); } $order->status = \App\Order::STATUS_SUCCESS; $order->saveOrFail(); $product->count_sold += $order->count; $product->saveOrFail(); return FundHelper::ACTION_CONTINUE; } }) ) { if ($product->count_warn > 0 && $product->count < $product->count_warn) { try { Mail::to($order->user->email)->Queue(new ProductCountWarn($product, $product->count)); } catch (\Throwable $e) { LogHelper::setLogFile('mail'); Log::error('shipOrder.count_warn error', [ 'product_id' => $order->product_id, 'email' => $order->user->email, 'exception' => $e->getMessage() ]); LogHelper::setLogFile('card'); } } if (System::_getInt('mail_send_order')) { $mail = @json_decode($order->contact_ext, true)['_mail']; if ($mail) { $order->sendEmail($mail); } } if ($order->status === \App\Order::STATUS_SUCCESS && System::_getInt('sms_send_order')) { $mobile = @json_decode($order->contact_ext, true)['_mobile']; if ($mobile) { $order->sendSms($mobile); } } } else { if ($order->status !== \App\Order::STATUS_UNPAY) { } else { Log::error('Pay.shipOrder.orderSuccess Failed.'); return FALSE; } } } else { Log::debug('Shop.Pay.shipOrder: .order_no:' . $order->order_no . ' already processed! #1'); } return FALSE; } private function showOrderResult($request, $order) { return self::renderResultPage($request, [ 'success' => true, 'msg' => $order->getSendMessage(), ], [ 'card_txt' => join('&#013;&#010;', $order->getCardsArray()), 'order' => $order, 'product' => $order->product ]); } } 